        return;
    }
    setIsSyncing(true);
    try {
        await fetch(googleScriptUrl, {
            method: 'POST',
            mode: 'no-cors', 
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(bank)
        });
