Hãy soạn một bài giảng slide (Study Guide) chi tiết cho:
Môn: ${config.subject}
Lớp: ${config.grade}
Chủ đề: "${config.topic}"

YÊU CẦU NỘI DUNG:
1. Tổng quan bài học hấp dẫn.
2. Mục tiêu và Năng lực cần đạt rõ ràng (theo định hướng GDPT 2018).
3. Phân hóa dạy học: Kế hoạch hỗ trợ học sinh Cơ bản, Nâng cao, Vận dụng.
4. Các phần (sections) tương ứng với các slide/hoạt động dạy học.
   - Mỗi section có tiêu đề, nội dung chính (Content).
   - Ví dụ minh họa (Examples) có lời giải chi tiết.
   - Câu hỏi gợi mở (Guiding Questions) để giáo viên tương tác.
   - Hoạt động (Activities) đề xuất (ví dụ: Thảo luận nhóm, Trò chơi...).
5. Exit Ticket: 2-3 câu hỏi kiểm tra cuối giờ.

QUY TẮC ĐỊNH DẠNG & TRÌNH BÀY:
- LaTeX: Dùng $...$ cho công thức toán. Escape backslash (\\\\) trong chuỗi JSON.
- Content & Solution: Sử dụng ký tự \\n để ngắt dòng giữa các ý hoặc các bước giải. Ứng dụng sẽ sử dụng tính năng "Click để hiện tiếp" dựa trên ký tự này.
- DifferentiationLevel trong section: Chọn "Cơ bản", "Nâng cao" hoặc "Vận dụng".

TRẢ VỀ JSON KHỚP SCHEMA.
  `;

  // Define Schemas for Study Guide
  const exampleSchema = {
    type: Type.OBJECT,
    properties: {
      problem: { type: Type.STRING },
      solution: { type: Type.STRING },
      explanation: { type: Type.STRING },
    },
    required: ["problem", "solution", "explanation"],
  };

  const theorySectionSchema = {
    type: Type.OBJECT,
    properties: {
      title: { type: Type.STRING },
      objectives: { type: Type.ARRAY, items: { type: Type.STRING } },
      competencies: { type: Type.ARRAY, items: { type: Type.STRING } },
      differentiationLevel: { type: Type.STRING },
      content: { type: Type.STRING },
      examples: { type: Type.ARRAY, items: exampleSchema },
      guidingQuestions: { type: Type.ARRAY, items: { type: Type.STRING } },
      activities: { type: Type.ARRAY, items: { type: Type.STRING } },
    },
    required: ["title", "content", "examples"],
  };

  const differentiationPlanSchema = {
    type: Type.OBJECT,
    properties: {
      basic: { type: Type.ARRAY, items: { type: Type.STRING } },
      advanced: { type: Type.ARRAY, items: { type: Type.STRING } },
      application: { type: Type.ARRAY, items: { type: Type.STRING } },
    }
  };

  const studyGuideSchema = {
    type: Type.OBJECT,
    properties: {
      topic: { type: Type.STRING },
      overview: { type: Type.STRING },
      objectives: { type: Type.ARRAY, items: { type: Type.STRING } },
      competencies: { type: Type.ARRAY, items: { type: Type.STRING } },
      differentiation: differentiationPlanSchema,
      exitTicket: { type: Type.ARRAY, items: { type: Type.STRING } },
      sections: { type: Type.ARRAY, items: theorySectionSchema },
    },
    required: ["topic", "overview", "sections"],
  };

  try {
    const parts: any[] = [{ text: promptText }];
    if (config.uploadedFile) {
        parts.push({ inlineData: { mimeType: config.uploadedFile.mimeType, data: config.uploadedFile.data } });
    }

    const response = await ai.models.generateContent({
      model: modelName,
      contents: { parts: parts },
      config: {
        responseMimeType: "application/json",
        responseSchema: studyGuideSchema,
        temperature: 0.4,
      },
    });
    return JSON.parse(response.text) as StudyGuideData;
  } catch (error: any) {
    console.error("Lỗi sinh bài giảng:", error);
    throw new Error("Lỗi sinh bài giảng: " + (error.message || "Vui lòng kiểm tra API Key."));
  }
};

export const generatePolyaSolution = async (config: ExamConfig, apiKey?: string): Promise<PolyaData> => {
  const ai = createClient(apiKey);
  const modelName = "gemini-2.5-flash";

  const promptText = `
  Bạn là một giáo sư toán học lỗi lạc, người áp dụng phương pháp của George Polya để hướng dẫn học sinh giải toán.
  Hãy phân tích bài toán sau đây theo 4 bước của Polya.

  BÀI TOÁN: "${config.topic}"

  QUY TẮC QUAN TRỌNG VỀ ĐỊNH DẠNG JSON:
  1. Trả về đúng định dạng JSON.
  2. Với các công thức Toán học (LaTeX), bạn PHẢI sử dụng double backslash (\\\\) thay vì single backslash (\\).
     Ví dụ: Viết "$\\\\frac{1}{2}$" thay vì "$\\frac{1}{2}$".
  3. TRÌNH BÀY: Sử dụng \\n để tách dòng các bước tư duy. Ứng dụng sẽ hiển thị từng dòng khi click (Click-to-reveal).

  YÊU CẦU ĐẦU RA (JSON):
  Hãy trả về một object JSON duy nhất với cấu trúc sau:
  {
    "title": "Tên ngắn gọn của bài toán",
    "problem": "Nội dung bài toán (có thể format lại cho đẹp bằng LaTeX)",
    "steps": [
      {
        "stepName": "Bước 1: Tìm hiểu đề bài",
        "icon": "search",
        "content": "Phân tích giả thiết (Cái đã cho), kết luận (Cái cần tìm).\\nVẽ hình nếu cần thiết (mô tả bằng lời).\\nĐịnh dạng LaTeX $...$ chuẩn.",
        "keyPoints": ["Giả thiết: ...", "Yêu cầu: ..."]
      },
      {
        "stepName": "Bước 2: Xây dựng chương trình giải",
        "icon": "map",
        "content": "Tìm mối liên hệ giữa giả thiết và kết luận.\\nNhớ lại các định lý, công thức liên quan.\\nLập kế hoạch từng bước.",
        "keyPoints": ["Sử dụng định lý...", "Đặt ẩn phụ...", "Chứng minh..."]
      },
      {
        "stepName": "Bước 3: Thực hiện chương trình giải",
        "icon": "wrench",
        "content": "Trình bày lời giải chi tiết, rõ ràng, tính toán chính xác.\\nDùng LaTeX cho công thức.\\nTách các bước tính bằng \\n.",
        "keyPoints": []
      },
      {
        "stepName": "Bước 4: Kiểm tra và khai thác",
        "icon": "check",
        "content": "Kiểm tra lại kết quả.\\nThử lại bằng cách khác (nếu có).\\nMở rộng bài toán hoặc tổng quát hóa.",
        "keyPoints": ["Cách khác: ...", "Bài toán tương tự..."]
      }
    ]
  }
  `;

  const polyaSchema = {
    type: Type.OBJECT,
    properties: {
      title: { type: Type.STRING },
      problem: { type: Type.STRING },
      steps: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            stepName: { type: Type.STRING },
            icon: { type: Type.STRING },
            content: { type: Type.STRING },
            keyPoints: { type: Type.ARRAY, items: { type: Type.STRING } }
          },
          required: ["stepName", "icon", "content", "keyPoints"]
        }
      }
    },
    required: ["title", "problem", "steps"]
  };

  try {
    const parts: any[] = [{ text: promptText }];
    if (config.uploadedFile) {
        parts.push({ inlineData: { mimeType: config.uploadedFile.mimeType, data: config.uploadedFile.data } });
    }

    const response = await ai.models.generateContent({
      model: modelName,
      contents: { parts: parts },
      config: {
        responseMimeType: "application/json",
        responseSchema: polyaSchema,
        temperature: 0.3,
      },
    });

    return JSON.parse(response.text) as PolyaData;
  } catch (error: any) {
    console.error("Lỗi sinh Polya:", error);
    throw new Error("Lỗi hệ thống AI: " + (error.message || "Vui lòng kiểm tra API Key."));
  }
};

import React, { useState, useEffect } from 'react';
import { ExamConfig, ExamMatrix, StudyGuideData, ExportData, PolyaData } from './types';
import { generateExam, generateStudyGuide, generatePolyaSolution } from './services/geminiService';
import ConfigForm from './components/ConfigForm';
import { ExamPreview } from './components/ExamPreview';
import StudyGuidePreview from './components/StudyGuidePreview';
import PolyaPreview from './components/PolyaPreview';
import LessonEditor from './components/LessonEditor';
import QuestionBank from './components/QuestionBank'; 
import SaveModal from './components/SaveModal'; // Import new component
import { 
  GraduationCap, Loader2, Moon, Sun, AlertTriangle, 
  User, School, Download, Keyboard, X, Info, 
  Sparkles, Zap, BookOpen, LayoutDashboard, ArrowRight,
  FileText, Presentation, Table2, ShieldCheck, ChevronRight,
  Footprints, HelpCircle, FileCode, CheckSquare, MessageSquare, Copy, Check, PenTool, Database, FileJson, Settings, Key
} from 'lucide-react';

type AppStep = 'landing' | 'dashboard' | 'config' | 'preview' | 'editor';

// Interface for Bank Item with Tags
interface BankItem {
  id: string;
  title: string;
  tags?: string[]; // Added tags
  date: number;
  type: 'exam' | 'theory' | 'polya';
  data: any;
  config: ExamConfig;
}

const App: React.FC = () => {
  const [step, setStep] = useState<AppStep>('landing');
  const [loading, setLoading] = useState(false);
  const [config, setConfig] = useState<ExamConfig | null>(null);
  const [role, setRole] = useState<'teacher' | 'student' | null>(null);
  const [selectedMode, setSelectedMode] = useState<'exam' | 'matrix' | 'theory' | 'polya' | null>(null);
  const [showUserGuide, setShowUserGuide] = useState(false);
  const [showQuestionBank, setShowQuestionBank] = useState(false); 
  const [showGlobalSettings, setShowGlobalSettings] = useState(false);

  // Custom API Key State
  const [apiKey, setApiKey] = useState(() => {
    try {
      if (typeof window !== 'undefined') {
        return localStorage.getItem('user_gemini_api_key') || '';
      }
    } catch(e) {}
    return '';
  });

  // Save Modal States
  const [showSaveModal, setShowSaveModal] = useState(false);
  const [pendingSaveData, setPendingSaveData] = useState<{type: 'exam'|'theory'|'polya', data: any} | null>(null);

  const [bank, setBank] = useState<BankItem[]>([]); 
  const [googleScriptUrl, setGoogleScriptUrl] = useState<string>(''); 
  const [isSyncing, setIsSyncing] = useState(false);

  const [guideTab, setGuideTab] = useState<'general' | 'shortcuts' | 'templates' | 'faq' | 'prompts'>('general');
  const [copiedPrompt, setCopiedPrompt] = useState<string | null>(null);

  const [isDarkMode, setIsDarkMode] = useState(() => {
    try {
      if (typeof window !== 'undefined') {
        const saved = localStorage.getItem('theme');
        if (saved) return saved === 'dark';
        return window.matchMedia('(prefers-color-scheme: dark)').matches;
      }
    } catch (e) {}
    return false;
  });

  const handleSaveApiKey = (key: string) => {
    setApiKey(key);
    localStorage.setItem('user_gemini_api_key', key);
    alert('Đã lưu API Key thành công!');
    setShowGlobalSettings(false);
  };

  // Global Shortcut for Dark Mode
  useEffect(() => {
    const handleGlobalKeyDown = (e: KeyboardEvent) => {
      // Ignore if user is typing in an input
      if (e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement) return;

      if (e.key.toLowerCase() === 'q') {
        setIsDarkMode(prev => !prev);
      }
    };

    window.addEventListener('keydown', handleGlobalKeyDown);
    return () => window.removeEventListener('keydown', handleGlobalKeyDown);
  }, []);

  // Load Bank and Settings
  useEffect(() => {
    try {
      const savedBank = localStorage.getItem('ai_studio_bank');
      if (savedBank) {
        setBank(JSON.parse(savedBank));
      }
      const savedUrl = localStorage.getItem('ai_studio_gas_url');
      if (savedUrl) {
        setGoogleScriptUrl(savedUrl);
      }
    } catch (e) {
      console.error("Failed to load data from storage", e);
    }
  }, []);

  // Save Bank to Storage
  useEffect(() => {
    try {
      localStorage.setItem('ai_studio_bank', JSON.stringify(bank));
    } catch (e) {
      console.error("Failed to save bank to storage", e);
      alert("Cảnh báo: Bộ nhớ trình duyệt đã đầy. Một số bài học có thể không được lưu. Hãy xóa bớt bài cũ hoặc đồng bộ lên Google Sheet.");
    }
  }, [bank]);

  const handleSaveConfig = (url: string) => {
    setGoogleScriptUrl(url);
    localStorage.setItem('ai_studio_gas_url', url);
    alert("Đã lưu địa chỉ kết nối Google Sheet.");
  };

  useEffect(() => {
    const html = document.documentElement;
    if (isDarkMode) {
      html.classList.add('dark');
      localStorage.setItem('theme', 'dark');
    } else {
      html.classList.remove('dark');
      localStorage.setItem('theme', 'light');
    }
  }, [isDarkMode]);

  const [examData, setExamData] = useState<ExamMatrix | null>(null);
  const [studyGuideData, setStudyGuideData] = useState<StudyGuideData | null>(null);
  const [polyaData, setPolyaData] = useState<PolyaData | null>(null);
  const [error, setError] = useState<string | null>(null);

  // --- Bank Functions ---
  const handleSaveToBank = () => {
    if (!config) return;

    let currentData;
    let type: 'exam' | 'theory' | 'polya' = 'exam';

    if (config.mode === 'theory') {
        currentData = studyGuideData;
        type = 'theory';
    } else if (config.mode === 'polya') {
        currentData = polyaData;
        type = 'polya';
    } else {
        currentData = examData;
        type = 'exam';
    }

    if (!currentData) return;

    // Check size roughly
    const jsonString = JSON.stringify(currentData);
    if (jsonString.length > 3000000) { 
        if (!confirm("Bài học này có dung lượng lớn (có thể do chứa nhiều ảnh). Việc lưu có thể làm đầy bộ nhớ trình duyệt. Bạn có muốn tiếp tục?")) return;
    }

    setPendingSaveData({ type, data: currentData });
    setShowSaveModal(true);
  };

  const executeSaveToBank = (title: string, tags: string[]) => {
    if (!pendingSaveData || !config) return;

    const newItem: BankItem = {
        id: Date.now().toString(),
        title: title,
        tags: tags,
        date: Date.now(),
        type: pendingSaveData.type,
        data: pendingSaveData.data,
        config: config
    };

    setBank(prev => [newItem, ...prev]);
    setShowSaveModal(false);
    setPendingSaveData(null);
    alert("Đã lưu vào Ngân hàng bài học thành công!");
  };

  const handleDeleteFromBank = (id: string) => {
    if (confirm("Bạn có chắc chắn muốn xóa bài này khỏi ngân hàng?")) {
        setBank(prev => prev.filter(item => item.id !== id));
    }
  };

  const handleRenameBankItem = (id: string) => {
    const item = bank.find(b => b.id === id);
    if (!item) return;
    const newTitle = window.prompt("Nhập tên mới cho bài học:", item.title);
    if (newTitle && newTitle.trim() !== "") {
        setBank(prev => prev.map(b => b.id === id ? { ...b, title: newTitle } : b));
    }
  };

  const handleLoadFromBank = (item: BankItem) => {
    setConfig(item.config);
    if (item.type === 'theory') {
        setStudyGuideData(item.data);
        setExamData(null);
        setPolyaData(null);
    } else if (item.type === 'polya') {
        setPolyaData(item.data);
        setExamData(null);
        setStudyGuideData(null);
    } else {
        setExamData(item.data);
        setStudyGuideData(null);
        setPolyaData(null);
    }
    setRole('teacher');
    setShowQuestionBank(false);
    setStep('preview');
  };

  const handleImportBank = (file: File) => {
    const reader = new FileReader();
    reader.onload = (e) => {
        try {
            const jsonStr = e.target?.result as string;
            const imported = JSON.parse(jsonStr);
            if (Array.isArray(imported)) {
                setBank(prev => [...imported, ...prev]);
                alert(`Đã nhập ${imported.length} bài vào ngân hàng.`);
            } else {
                alert("File không đúng định dạng ngân hàng.");
            }
        } catch (err) {
            alert("Lỗi đọc file.");
        }
    };
    reader.readAsText(file);
  };

  // --- Cloud Sync ---
  const handleSyncUp = async () => {
    if (!googleScriptUrl) {
        alert("Vui lòng cấu hình URL Google Web App trong phần Cài đặt của Ngân hàng.");
        return;
    }
    setIsSyncing(true);
    try {
        await fetch(googleScriptUrl, {
            method: 'POST',
            mode: 'no-cors', 
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(bank)
        });
        alert("Đã gửi yêu cầu đồng bộ. Do giới hạn CORS, ứng dụng không thể xác minh kết quả; hãy kiểm tra Google Sheet.");
    } catch (e) {
        console.error(e);
        alert("Lỗi kết nối đến Google Sheet. Kiểm tra lại URL và mạng.");
    } finally {
        setIsSyncing(false);
    }
  };

  const handleSyncDown = async () => {
    if (!googleScriptUrl) {
        alert("Vui lòng cấu hình URL Google Web App trong phần Cài đặt của Ngân hàng.");
        return;
    }
    setIsSyncing(true);
    try {
        const response = await fetch(googleScriptUrl);
        const data = await response.json();
        if (Array.isArray(data)) {
            const currentIds = new Set(bank.map(b => b.id));
            const newItems = data.filter((item: BankItem) => !currentIds.has(item.id));

            if (newItems.length > 0) {
                setBank(prev => [...newItems, ...prev]);
                alert(`Đã tải về ${newItems.length} bài học mới từ Google Sheet.`);
            } else {
                alert("Dữ liệu trên máy đã cập nhật mới nhất so với Sheet.");
            }
        } else {
            alert("Dữ liệu từ Sheet không đúng định dạng.");
        }
    } catch (e) {
        console.error(e);
        alert("Lỗi tải dữ liệu từ Google Sheet. Hãy chắc chắn bạn đã triển khai Web App với quyền 'Anyone'.");
    } finally {
        setIsSyncing(false);
    }
  };

  const handleGenerate = async (newConfig: ExamConfig) => {
    setLoading(true);
    setError(null);
    setConfig(newConfig);

    // Pass apiKey to service functions
    const activeKey = apiKey || undefined;

    try {
      if (newConfig.mode === 'theory') {
        const data = await generateStudyGuide(newConfig, activeKey);
        setStudyGuideData(data);
        setExamData(null);
        setPolyaData(null);
      } else if (newConfig.mode === 'polya') {
        const data = await generatePolyaSolution(newConfig, activeKey);
        setPolyaData(data);
        setExamData(null);
        setStudyGuideData(null);
      } else {
        const data = await generateExam(newConfig, activeKey);
        setExamData(data);
        setStudyGuideData(null);
        setPolyaData(null);
      }
      setStep('preview');
    } catch (err: any) {
      console.error(err);
      setError(err.message || "Lỗi hệ thống AI. Vui lòng thử lại sau.");
    } finally {
      setLoading(false);
    }
  };

  const handleModeSelection = (mode: 'exam' | 'matrix' | 'theory' | 'polya') => {
    setSelectedMode(mode);
    setStep('config');
  };

  const handleReset = () => {
    setStep('landing');
    setRole(null);
    setSelectedMode(null);
    setExamData(null);
    setStudyGuideData(null);
    setPolyaData(null);
    setError(null);
  };

  const isRecord = (value: unknown): value is Record<string, any> =>
    typeof value === 'object' && value !== null;

  const isValidExamConfig = (value: unknown): value is ExamConfig => {
    if (!isRecord(value)) return false;
    return (
      typeof value.mode === 'string' &&
      typeof value.subject === 'string' &&
      typeof value.grade === 'string' &&
      typeof value.topic === 'string'
    );
  };

  const isValidExamMatrix = (value: unknown): value is ExamMatrix => {
    if (!isRecord(value)) return false;
    return typeof value.summary === 'string' && Array.isArray(value.questions);
  };

  const isValidStudyGuideData = (value: unknown): value is StudyGuideData => {
    if (!isRecord(value)) return false;
    return (
      typeof value.topic === 'string' &&
      typeof value.overview === 'string' &&
      Array.isArray(value.sections)
    );
  };

  const isValidPolyaData = (value: unknown): value is PolyaData => {
    if (!isRecord(value)) return false;
    return (
      typeof value.title === 'string' &&
      typeof value.problem === 'string' &&
      Array.isArray(value.steps)
    );
  };

  const handleImport = (file: File) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const jsonStr = e.target?.result as string;
        const imported = JSON.parse(jsonStr) as any;

        // Basic validation - check if it's a direct JSON data import (from ChatGPT/External)
        // or a full ExportData from this app
        let configToUse = imported.config;
        let dataToUse = imported.data;
        let typeToUse = imported.type;

        // Auto-detect manual JSON import (simpler structure)
        if (!configToUse) {
            // Try to infer
            if (imported.questions && Array.isArray(imported.questions)) {
                typeToUse = 'exam';
                dataToUse = imported as any;
                configToUse = { mode: 'exam', subject: 'Khác', grade: 'Khác', topic: 'Imported Exam' };
            } else if (imported.sections && Array.isArray(imported.sections)) {
                typeToUse = 'theory';
                dataToUse = imported as any;
                configToUse = { mode: 'theory', subject: 'Khác', grade: 'Khác', topic: 'Imported Lesson' };
            } else if (imported.steps && Array.isArray(imported.steps)) {
                typeToUse = 'polya';
                dataToUse = imported as any;
                configToUse = { mode: 'polya', subject: 'Khác', grade: 'Khác', topic: 'Imported Polya' };
            }
        }

        if (typeToUse === 'theory') {
          setStudyGuideData(dataToUse as StudyGuideData);
          setExamData(null);
          setPolyaData(null);
        } else if (typeToUse === 'polya') {
          setPolyaData(dataToUse as PolyaData);
          setExamData(null);
          setStudyGuideData(null);
        } else {
          setExamData(dataToUse as ExamMatrix);
          setStudyGuideData(null);
          setPolyaData(null);
        }
        setConfig(configToUse);
        setStep('preview');
        setRole('teacher');
        setError(null);
