import { GoogleGenAI, Type } from "@google/genai";
import { ExamConfig, Question, QuestionType, ExamMatrix, StudyGuideData, MatrixRow, DifficultyLevel, PolyaData } from "../types";

const createClient = (apiKey?: string) => {
  // Prioritize custom key, fallback to env, then empty string (which will cause SDK error)
  const key = apiKey || process.env.API_KEY || "";
  return new GoogleGenAI({ apiKey: key });
};

export const suggestMatrixStructure = async (subject: string, grade: string, title: string, apiKey?: string): Promise<MatrixRow[]> => {
  const ai = createClient(apiKey);
  const modelName = "gemini-2.5-flash";

  const prompt = `
Bạn là chuyên gia khảo thí. Hãy gợi ý một cấu trúc ma trận đề thi chuẩn cho:
Môn: ${subject}
Lớp: ${grade}
Tiêu đề/Phạm vi: ${title}

TRẢ VỀ JSON MẢNG MatrixRow:
[
  { "topic": "Tên chuyên đề", "level": "Mức độ", "count": số_câu, "type": "Loại câu" }
]
  `;

  try {
    const response = await ai.models.generateContent({
      model: modelName,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
      },
    });
    return JSON.parse(response.text) as MatrixRow[];
  } catch (error) {
    console.error("Matrix suggestion failed:", error);
    return [];
  }
};

export const generateExam = async (config: ExamConfig, apiKey?: string): Promise<ExamMatrix> => {
  const ai = createClient(apiKey);
  const modelName = "gemini-2.5-flash"; // Updated model for better performance/cost balance

  let structureInstruction = "";
  if (config.mode === 'matrix' && config.matrixRows) {
      config.matrixRows.forEach((row, idx) => {
          structureInstruction += `- Phần ${idx+1}: ${row.count} câu, Chủ đề: "${row.topic}", Mức: ${row.level}, Dạng: ${row.type}.\n`;
      });
  } else {
      structureInstruction = `Chủ đề: "${config.topic}", Số lượng: ${config.questionCount} câu, Dạng: ${config.questionType}, Mức độ ưu tiên: ${config.difficultyMode === 'fixed' ? config.targetLevel : 'Phân hóa từ Nhận biết đến Vận dụng cao'}.`;
  }

  // Nâng cấp Prompt để đáp ứng tiêu chuẩn giáo viên 20 năm kinh nghiệm
  // Cập nhật: Yêu cầu lời giải ngắn gọn, xúc tích, thay số nhanh + BẮT BUỘC XUỐNG DÒNG \n
  let promptText = `
VAI TRÒ: Bạn là một TỔ TRƯỞNG CHUYÊN MÔN TOÁN XUẤT SẮC CÓ 20 NĂM KINH NGHIỆM.
Phong cách: Chặt chẽ về bản chất nhưng CỰC KỲ NGẮN GỌN, XÚC TÍCH trong trình bày.

NHIỆM VỤ: Soạn một chuyên đề luyện tập môn ${config.subject} lớp ${config.grade}.

YÊU CẦU CẤU TRÚC JSON (BẮT BUỘC):
1. keyConcepts (Kiến thức trọng tâm): Tóm tắt công thức và định lý quan trọng nhất.

2. questions (Danh sách câu hỏi):
   - NỘI DUNG CÂU HỎI: Rõ ràng, số liệu tính toán ra kết quả đẹp.
   - OPTIONS: 4 phương án nhiễu thông minh.
   - DIFFICULTY: Dán nhãn chính xác.
   - SOLUTION (Lời giải chi tiết - QUAN TRỌNG):
     + YÊU CẦU CỐT LÕI: Lời giải phải NGẮN GỌN, XÚC TÍCH. Đi thẳng vào công thức và phép tính.
     + ĐỊNH DẠNG: BẮT BUỘC dùng ký tự \\n để ngắt dòng giữa các bước giải. Ví dụ: "Bước 1...\\nBước 2...\\nKết luận...".
     + KHÔNG viết văn hoa, dài dòng. KHÔNG giải thích lại đề bài.
     + Phần thay số: Viết gộp bước. Ví dụ thay vì viết "Ta có 2 + 3 = 5, suy ra x = 5", hãy viết "Ta có: $x = 2 + 3 = 5$".
     + Bỏ qua các bước biến đổi đại số quá cơ bản.
     + SỬ DỤNG LATEX: Mọi công thức phải đặt trong $...$. Escape backslash kép (\\\\).

NỘI DUNG CỤ THỂ CẦN SOẠN:
${structureInstruction}

HÃY TRẢ VỀ JSON CHUẨN THEO SCHEMA DƯỚI ĐÂY.
  `;

  const questionSchema = {
    type: Type.OBJECT,
    properties: {
      id: { type: Type.INTEGER },
      content: { type: Type.STRING },
      type: { type: Type.STRING },
      difficulty: { type: Type.STRING },
      options: { type: Type.ARRAY, items: { type: Type.STRING } },
      correctAnswer: { type: Type.STRING },
      solution: { type: Type.STRING },
      hints: { type: Type.ARRAY, items: { type: Type.STRING } },
      differentiation: { type: Type.STRING, description: "Phân hóa (Cơ bản/Nâng cao/Vận dụng)"}
    },
    required: ["id", "content", "type", "difficulty", "correctAnswer", "solution", "hints", "options"],
  };

  const responseSchema = {
    type: Type.OBJECT,
    properties: {
      summary: { type: Type.STRING },
      keyConcepts: { type: Type.STRING, description: "Tóm tắt kiến thức trọng tâm, công thức quan trọng của chuyên đề." },
      objectives: { type: Type.ARRAY, items: { type: Type.STRING } },
      competencies: { type: Type.ARRAY, items: { type: Type.STRING } },
      questions: {
        type: Type.ARRAY,
        items: questionSchema,
      },
    },
    required: ["summary", "keyConcepts", "questions"],
  };

  try {
    const parts: any[] = [{ text: promptText }];
    if (config.uploadedFile) {
        parts.push({ inlineData: { mimeType: config.uploadedFile.mimeType, data: config.uploadedFile.data } });
    }

    const response = await ai.models.generateContent({
      model: modelName,
      contents: { parts: parts },
      config: {
        responseMimeType: "application/json",
        responseSchema: responseSchema,
        temperature: 0.3, // Giảm temperature để tăng độ chính xác toán học
      },
    });

    const parsed = JSON.parse(response.text);
    return parsed as ExamMatrix;
  } catch (error: any) {
    console.error("Lỗi sinh đề:", error);
    throw new Error("Lỗi hệ thống AI: " + (error.message || "Vui lòng kiểm tra API Key."));
  }
};

export const generateStudyGuide = async (config: ExamConfig, apiKey?: string): Promise<StudyGuideData> => {
  const ai = createClient(apiKey);
  const modelName = "gemini-2.5-flash";

  const promptText = `
Bạn là chuyên gia sư phạm và thiết kế bài giảng điện tử.
Hãy soạn một bài giảng slide (Study Guide) chi tiết cho:
Môn: ${config.subject}
Lớp: ${config.grade}
Chủ đề: "${config.topic}"

YÊU CẦU NỘI DUNG:
1. Tổng quan bài học hấp dẫn.
2. Mục tiêu và Năng lực cần đạt rõ ràng (theo định hướng GDPT 2018).
3. Phân hóa dạy học: Kế hoạch hỗ trợ học sinh Cơ bản, Nâng cao, Vận dụng.
4. Các phần (sections) tương ứng với các slide/hoạt động dạy học.
   - Mỗi section có tiêu đề, nội dung chính (Content).
   - Ví dụ minh họa (Examples) có lời giải chi tiết.
   - Câu hỏi gợi mở (Guiding Questions) để giáo viên tương tác.
   - Hoạt động (Activities) đề xuất (ví dụ: Thảo luận nhóm, Trò chơi...).
5. Exit Ticket: 2-3 câu hỏi kiểm tra cuối giờ.

QUY TẮC ĐỊNH DẠNG & TRÌNH BÀY:
- LaTeX: Dùng $...$ cho công thức toán. Escape backslash (\\\\) trong chuỗi JSON.
- Content & Solution: QUAN TRỌNG! Sử dụng ký tự \\n để ngắt dòng giữa các ý hoặc các bước giải. Ứng dụng sẽ sử dụng tính năng "Click để hiện tiếp" dựa trên ký tự này.
- DifferentiationLevel trong section: Chọn "Cơ bản", "Nâng cao" hoặc "Vận dụng".

TRẢ VỀ JSON KHỚP SCHEMA.
  `;

  // Define Schemas for Study Guide
  const exampleSchema = {
    type: Type.OBJECT,
    properties: {
      problem: { type: Type.STRING },
      solution: { type: Type.STRING },
      explanation: { type: Type.STRING },
    },
    required: ["problem", "solution", "explanation"],
  };

  const theorySectionSchema = {
    type: Type.OBJECT,
    properties: {
      title: { type: Type.STRING },
      objectives: { type: Type.ARRAY, items: { type: Type.STRING } },
      competencies: { type: Type.ARRAY, items: { type: Type.STRING } },
      differentiationLevel: { type: Type.STRING },
      content: { type: Type.STRING },
      examples: { type: Type.ARRAY, items: exampleSchema },
      guidingQuestions: { type: Type.ARRAY, items: { type: Type.STRING } },
      activities: { type: Type.ARRAY, items: { type: Type.STRING } },
    },
    required: ["title", "content", "examples"],
  };

  const differentiationPlanSchema = {
    type: Type.OBJECT,
    properties: {
      basic: { type: Type.ARRAY, items: { type: Type.STRING } },
      advanced: { type: Type.ARRAY, items: { type: Type.STRING } },
      application: { type: Type.ARRAY, items: { type: Type.STRING } },
    }
  };

  const studyGuideSchema = {
    type: Type.OBJECT,
    properties: {
      topic: { type: Type.STRING },
      overview: { type: Type.STRING },
      objectives: { type: Type.ARRAY, items: { type: Type.STRING } },
      competencies: { type: Type.ARRAY, items: { type: Type.STRING } },
      differentiation: differentiationPlanSchema,
      exitTicket: { type: Type.ARRAY, items: { type: Type.STRING } },
      sections: { type: Type.ARRAY, items: theorySectionSchema },
    },
    required: ["topic", "overview", "sections"],
  };

  try {
    const parts: any[] = [{ text: promptText }];
    if (config.uploadedFile) {
        parts.push({ inlineData: { mimeType: config.uploadedFile.mimeType, data: config.uploadedFile.data } });
    }

    const response = await ai.models.generateContent({
      model: modelName,
      contents: { parts: parts },
      config: {
        responseMimeType: "application/json",
        responseSchema: studyGuideSchema,
        temperature: 0.4,
      },
    });
    return JSON.parse(response.text) as StudyGuideData;
  } catch (error: any) {
    console.error("Lỗi sinh bài giảng:", error);
    throw new Error("Lỗi sinh bài giảng: " + (error.message || "Vui lòng kiểm tra API Key."));
  }
};

export const generatePolyaSolution = async (config: ExamConfig, apiKey?: string): Promise<PolyaData> => {
  const ai = createClient(apiKey);
  const modelName = "gemini-2.5-flash";

  const promptText = `
  Bạn là một giáo sư toán học lỗi lạc, người áp dụng phương pháp của George Polya để hướng dẫn học sinh giải toán.
  Hãy phân tích bài toán sau đây theo 4 bước của Polya.

  BÀI TOÁN: "${config.topic}"

  QUY TẮC QUAN TRỌNG VỀ ĐỊNH DẠNG JSON:
  1. Trả về đúng định dạng JSON.
  2. Với các công thức Toán học (LaTeX), bạn PHẢI sử dụng double backslash (\\\\) thay vì single backslash (\\).
     Ví dụ: Viết "$\\\\frac{1}{2}$" thay vì "$\\frac{1}{2}$".
  3. TRÌNH BÀY: QUAN TRỌNG! Sử dụng \\n để tách dòng các bước tư duy. Ứng dụng sẽ hiển thị từng dòng khi click (Click-to-reveal).

  YÊU CẦU ĐẦU RA (JSON):
  Hãy trả về một object JSON duy nhất với cấu trúc sau:
  {
    "title": "Tên ngắn gọn của bài toán",
    "problem": "Nội dung bài toán (có thể format lại cho đẹp bằng LaTeX)",
    "steps": [
      {
        "stepName": "Bước 1: Tìm hiểu đề bài",
        "icon": "search",
        "content": "Phân tích giả thiết (Cái đã cho), kết luận (Cái cần tìm).\\nVẽ hình nếu cần thiết (mô tả bằng lời).\\nĐịnh dạng LaTeX $...$ chuẩn.",
        "keyPoints": ["Giả thiết: ...", "Yêu cầu: ..."]
      },
      {
        "stepName": "Bước 2: Xây dựng chương trình giải",
        "icon": "map",
        "content": "Tìm mối liên hệ giữa giả thiết và kết luận.\\nNhớ lại các định lý, công thức liên quan.\\nLập kế hoạch từng bước.",
        "keyPoints": ["Sử dụng định lý...", "Đặt ẩn phụ...", "Chứng minh..."]
      },
      {
        "stepName": "Bước 3: Thực hiện chương trình giải",
        "icon": "wrench",
        "content": "Trình bày lời giải chi tiết, rõ ràng, tính toán chính xác.\\nDùng LaTeX cho công thức.\\nTách các bước tính bằng \\n.",
        "keyPoints": []
      },
      {
        "stepName": "Bước 4: Kiểm tra và khai thác",
        "icon": "check",
        "content": "Kiểm tra lại kết quả.\\nThử lại bằng cách khác (nếu có).\\nMở rộng bài toán hoặc tổng quát hóa.",
        "keyPoints": ["Cách khác: ...", "Bài toán tương tự..."]
      }
    ]
  }
  `;

  const polyaSchema = {
    type: Type.OBJECT,
    properties: {
      title: { type: Type.STRING },
      problem: { type: Type.STRING },
      steps: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            stepName: { type: Type.STRING },
            icon: { type: Type.STRING },
            content: { type: Type.STRING },
            keyPoints: { type: Type.ARRAY, items: { type: Type.STRING } }
          },
          required: ["stepName", "icon", "content", "keyPoints"]
        }
      }
    },
    required: ["title", "problem", "steps"]
  };

  try {
    const parts: any[] = [{ text: promptText }];
    if (config.uploadedFile) {
        parts.push({ inlineData: { mimeType: config.uploadedFile.mimeType, data: config.uploadedFile.data } });
    }

    const response = await ai.models.generateContent({
      model: modelName,
      contents: { parts: parts },
      config: {
        responseMimeType: "application/json",
        responseSchema: polyaSchema,
        temperature: 0.3,
      },
    });

    return JSON.parse(response.text) as PolyaData;
  } catch (error: any) {
    console.error("Lỗi sinh Polya:", error);
    throw new Error("Lỗi hệ thống AI: " + (error.message || "Vui lòng kiểm tra API Key."));
  }
};

import React, { useState, useRef, useEffect } from 'react';
import { SUBJECTS, GRADES, DIFFICULTY_LEVELS, QUESTION_TYPES, SAMPLE_TOPICS } from '../constants';
import { ExamConfig, Subject, QuestionType, DifficultyLevel, GenMode, MatrixRow } from '../types';
import { BookOpen, Brain, Sparkles, Layers, ListChecks, Presentation as PresentationIcon, FileText, Upload, Image as ImageIcon, X, Paperclip, Plus, Trash2, Table2, Loader2, Footprints } from 'lucide-react';

interface ConfigFormProps {
  onGenerate: (config: ExamConfig) => void;
  isLoading: boolean;
  onImport: (file: File) => void;
  forcedMode?: GenMode; // Prop mới
}

const ConfigForm: React.FC<ConfigFormProps> = ({ onGenerate, isLoading, onImport, forcedMode }) => {
  const [mode, setMode] = useState<GenMode>(forcedMode || 'exam');
  const [subject, setSubject] = useState<Subject | string>(Subject.MATH);
  const [grade, setGrade] = useState<string>(GRADES[11]); 

  // Đồng bộ mode nếu forcedMode thay đổi
  useEffect(() => {
    if (forcedMode) setMode(forcedMode);
  }, [forcedMode]);

  // Single Mode State
  const [topic, setTopic] = useState<string>('');
  // New detailed fields
  const [problemReq, setProblemReq] = useState<string>(''); // Yêu cầu đặc biệt về dạng toán
  const [solutionReq, setSolutionReq] = useState<string>(''); // Yêu cầu về lời giải

  const [questionType, setQuestionType] = useState<QuestionType>(QuestionType.MULTIPLE_CHOICE);
  const [questionCount, setQuestionCount] = useState<number>(5);
  const [difficultyMode, setDifficultyMode] = useState<'progressive' | 'fixed'>('progressive');
  const [targetLevel, setTargetLevel] = useState<DifficultyLevel>(DifficultyLevel.MEDIUM);

  // Matrix Mode State
  const [matrixTitle, setMatrixTitle] = useState<string>('Đề ôn tập học kì');
  const [matrixRows, setMatrixRows] = useState<MatrixRow[]>([
    { topic: '', level: DifficultyLevel.EASY, count: 2, type: QuestionType.MULTIPLE_CHOICE },
    { topic: '', level: DifficultyLevel.MEDIUM, count: 2, type: QuestionType.MULTIPLE_CHOICE },
    { topic: '', level: DifficultyLevel.HARD, count: 1, type: QuestionType.ESSAY },
  ]);

  // File upload state
  const [uploadedFile, setUploadedFile] = useState<{name: string, data: string, mimeType: string} | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const resourceInputRef = useRef<HTMLInputElement>(null);

  const suggestedTopics = SAMPLE_TOPICS[subject as Subject] || [];

  const handleAddRow = () => {
    setMatrixRows([...matrixRows, { topic: '', level: DifficultyLevel.MEDIUM, count: 1, type: QuestionType.MULTIPLE_CHOICE }]);
  };

  const handleRemoveRow = (index: number) => {
    if (matrixRows.length > 1) {
      const newRows = [...matrixRows];
      newRows.splice(index, 1);
      setMatrixRows(newRows);
    }
  };

  const handleRowChange = (index: number, field: keyof MatrixRow, value: any) => {
    const newRows = [...matrixRows];
    newRows[index] = { ...newRows[index], [field]: value };
    setMatrixRows(newRows);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    let finalTopic = '';

    if (mode === 'matrix') {
        finalTopic = matrixTitle;
    } else {
        // Xử lý nội dung topic cho các chế độ đơn lẻ
        if (uploadedFile) {
            finalTopic = "Nội dung từ tài liệu đính kèm";
        } else {
            finalTopic = topic;
            // Gộp các yêu cầu chi tiết vào topic để gửi cho AI
            if (problemReq.trim()) {
                finalTopic += `\n[YÊU CẦU DẠNG TOÁN]: ${problemReq.trim()}`;
            }
            if (solutionReq.trim()) {
                finalTopic += `\n[YÊU CẦU LỜI GIẢI]: ${solutionReq.trim()}`;
            }
        }
    }

    onGenerate({
      mode,
      subject,
      grade,
      topic: finalTopic,
      questionType: mode === 'exam' ? questionType : undefined,
      questionCount: mode === 'exam' ? questionCount : undefined,
      difficultyMode: mode === 'exam' ? difficultyMode : undefined,
      targetLevel: mode === 'exam' && difficultyMode === 'fixed' ? targetLevel : undefined,
      matrixRows: mode === 'matrix' ? matrixRows : undefined,
      includeHints: true,
      uploadedFile: uploadedFile ? { data: uploadedFile.data, mimeType: uploadedFile.mimeType } : null
    });
  };

  const handleResourceFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      const reader = new FileReader();
      reader.onload = (event) => {
        const base64String = event.target?.result as string;
        const base64Data = base64String.split(',')[1];
        setUploadedFile({ name: file.name, mimeType: file.type, data: base64Data });
        if (mode !== 'matrix' && !topic) {
          setTopic("Nội dung tài liệu: " + file.name);
        }
      };
      reader.readAsDataURL(file);
    }
  };

  const clearUploadedFile = () => {
    setUploadedFile(null);
    if (mode !== 'matrix' && topic.startsWith("Nội dung tài liệu:")) {
        setTopic("");
    }
  };

  return (
    <div className="w-full bg-white dark:bg-slate-800 rounded-3xl shadow-2xl overflow-hidden border border-slate-200 dark:border-slate-700 relative transition-all duration-300">

      {/* Ẩn Tab nếu forcedMode được bật */}
      {!forcedMode && (
        <div className="flex border-b border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-900 overflow-x-auto">
          <button onClick={() => setMode('exam')} className={`flex-1 min-w-[140px] py-4 font-bold text-sm flex items-center justify-center gap-2 transition-colors border-b-2 ${mode === 'exam' ? 'border-blue-600 text-blue-700 bg-white' : 'border-transparent text-slate-500'}`}><ListChecks className="w-5 h-5" /> Đơn lẻ</button>
          <button onClick={() => setMode('matrix')} className={`flex-1 min-w-[140px] py-4 font-bold text-sm flex items-center justify-center gap-2 transition-colors border-b-2 ${mode === 'matrix' ? 'border-indigo-600 text-indigo-700 bg-white' : 'border-transparent text-slate-500'}`}><Table2 className="w-5 h-5" /> Tổng hợp</button>
          <button onClick={() => setMode('theory')} className={`flex-1 min-w-[140px] py-4 font-bold text-sm flex items-center justify-center gap-2 transition-colors border-b-2 ${mode === 'theory' ? 'border-teal-600 text-teal-700 bg-white' : 'border-transparent text-slate-500'}`}><PresentationIcon className="w-5 h-5" /> Lý thuyết</button>
          <button onClick={() => setMode('polya')} className={`flex-1 min-w-[140px] py-4 font-bold text-sm flex items-center justify-center gap-2 transition-colors border-b-2 ${mode === 'polya' ? 'border-orange-600 text-orange-700 bg-white' : 'border-transparent text-slate-500'}`}><Footprints className="w-5 h-5" /> G.Polya</button>
        </div>
      )}

      <div className="p-10 border-b border-slate-50 dark:border-slate-700">
        <h2 className={`text-3xl font-black flex items-center gap-3 ${
            mode === 'exam' ? 'text-blue-700' : mode === 'matrix' ? 'text-indigo-700' : mode === 'theory' ? 'text-teal-700' : 'text-orange-600'
        } dark:text-white`}>
          <Sparkles className="w-8 h-8 text-yellow-500" />
          {mode === 'exam' && 'Cấu hình Đề Chuyên Đề'}
          {mode === 'matrix' && 'Cấu hình Ma Trận Tổng Hợp'}
          {mode === 'theory' && 'Cấu hình Bài Giảng Slide'}
          {mode === 'polya' && 'Giải Toán G.Polya'}
        </h2>
        <p className="text-slate-500 dark:text-slate-400 mt-2 text-sm font-medium">Điền các thông tin cần thiết để AI bắt đầu quá trình sáng tạo.</p>
      </div>

      <form onSubmit={handleSubmit} className="p-10 space-y-10">
        {mode !== 'polya' && (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              <div className="space-y-2">
                <label className="text-xs font-black text-slate-400 uppercase tracking-widest">Môn học</label>
                <select 
                  value={subject} 
                  onChange={(e) => setSubject(e.target.value)}
                  className="w-full rounded-2xl border-slate-200 dark:border-slate-700 border-2 p-4 text-slate-800 dark:text-slate-100 font-black focus:ring-4 focus:ring-indigo-500/20 focus:border-indigo-500 bg-slate-50 dark:bg-slate-900 transition-all outline-none"
                >
                  {SUBJECTS.map((s) => <option key={s} value={s}>{s}</option>)}
                </select>
              </div>
              <div className="space-y-2">
                <label className="text-xs font-black text-slate-400 uppercase tracking-widest">Khối lớp</label>
                <select 
                  value={grade} 
                  onChange={(e) => setGrade(e.target.value)}
                  className="w-full rounded-2xl border-slate-200 dark:border-slate-700 border-2 p-4 text-slate-800 dark:text-slate-100 font-black focus:ring-4 focus:ring-indigo-500/20 focus:border-indigo-500 bg-slate-50 dark:bg-slate-900 transition-all outline-none"
                >
                  {GRADES.map((g) => <option key={g} value={g}>{g}</option>)}
                </select>
              </div>
          </div>
        )}

        {mode !== 'matrix' && (
            <div className="space-y-6">
                <div className="bg-slate-50 dark:bg-slate-900 p-8 rounded-[2rem] border-2 border-slate-100 dark:border-slate-700 relative">
                    <input type="file" ref={resourceInputRef} className="hidden" accept="image/*,application/pdf" onChange={handleResourceFileChange}/>

                    {!uploadedFile ? (
                        <div className="flex flex-col gap-6">
                            {/* TOPIC INPUT - Cụ thể tên chuyên đề */}
                            <div>
                                <label className="text-xs font-black text-slate-400 uppercase tracking-widest mb-3 block">
                                  {mode === 'polya' ? 'Nội dung bài toán' : 'Tên Chuyên Đề / Bài Học'}
                                </label>
                                <div className="flex gap-4">
                                    {mode === 'polya' ? (
                                        <textarea
                                          value={topic}
                                          onChange={(e) => setTopic(e.target.value)}
                                          placeholder="Nhập đề bài toán vào đây..."
                                          rows={4}
                                          className="flex-grow rounded-2xl border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 border-2 p-4 text-slate-900 dark:text-slate-100 font-bold focus:ring-4 focus:ring-indigo-500/20 outline-none resize-none"
                                        />
                                    ) : (
                                        <input
                                            type="text"
                                            value={topic}
                                            onChange={(e) => setTopic(e.target.value)}
                                            placeholder="VD: Sóng ánh sáng, Tích phân hàm ẩn..."
                                            className="flex-grow rounded-2xl border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 border-2 p-4 text-slate-900 dark:text-slate-100 font-bold focus:ring-4 focus:ring-indigo-500/20 outline-none"
                                        />
                                    )}
                                    <button
                                        type="button"
                                        onClick={() => resourceInputRef.current?.click()}
                                        className="flex-shrink-0 flex items-center gap-3 px-6 py-4 bg-white dark:bg-slate-800 border-2 border-indigo-200 dark:border-indigo-900 rounded-2xl text-indigo-700 dark:text-indigo-400 hover:bg-indigo-50 font-black transition-all shadow-sm"
                                    >
                                        <Paperclip className="w-5 h-5" /> <span className="hidden sm:inline">Ảnh/PDF</span>
                                    </button>
                                </div>
                            </div>

                            {/* EXTRA REQUIREMENTS FIELDS */}
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-6 pt-4 border-t border-slate-200 dark:border-slate-700">
                                <div>
                                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 block flex items-center gap-2">
                                        <Brain className="w-3 h-3"/> Yêu cầu đặc biệt về dạng toán (Tùy chọn)
                                    </label>
                                    <textarea 
                                        value={problemReq}
                                        onChange={(e) => setProblemReq(e.target.value)}
                                        placeholder="VD: Tập trung vào các bài toán thực tế, vận dụng cao, chứa tham số m..."
                                        rows={3}
                                        className="w-full rounded-2xl border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 border-2 p-3 text-sm text-slate-800 dark:text-slate-200 focus:ring-4 focus:ring-indigo-500/20 outline-none resize-none"
                                    />
                                </div>
                                <div>
                                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 block flex items-center gap-2">
                                        <Sparkles className="w-3 h-3"/> Yêu cầu về lời giải (Tùy chọn)
                                    </label>
                                    <textarea 
                                        value={solutionReq}
                                        onChange={(e) => setSolutionReq(e.target.value)}
                                        placeholder="VD: Lời giải ngắn gọn, dùng phương pháp ghép trục, giải bằng máy tính Casio..."
                                        rows={3}
                                        className="w-full rounded-2xl border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 border-2 p-3 text-sm text-slate-800 dark:text-slate-200 focus:ring-4 focus:ring-indigo-500/20 outline-none resize-none"
                                    />
                                </div>
                            </div>

                            {mode !== 'polya' && suggestedTopics.length > 0 && (
                            <div className="flex flex-wrap gap-2">
                                {suggestedTopics.map(t => (
                                <button key={t} type="button" onClick={() => setTopic(t)} className="text-[10px] font-black uppercase tracking-widest bg-white dark:bg-slate-800 hover:bg-indigo-600 hover:text-white text-slate-400 px-4 py-2 rounded-full border border-slate-200 dark:border-slate-700 transition-all">
                                    + {t}
                                </button>
                                ))}
                            </div>
                            )}
                        </div>
                    ) : (
                        <div className="flex items-center justify-between bg-white dark:bg-slate-800 border-4 border-indigo-50 dark:border-indigo-900/30 p-4 rounded-2xl shadow-lg animate-fade-in-up">
                            <div className="flex items-center gap-4 overflow-hidden">
                                <div className="bg-indigo-600 p-3 rounded-xl text-white">
                                    {uploadedFile.mimeType.includes('pdf') ? <FileText className="w-6 h-6"/> : <ImageIcon className="w-6 h-6"/>}
