      try {
        const jsonStr = e.target?.result as string;
        const imported = JSON.parse(jsonStr) as any;

        // Basic validation - check if it's a direct JSON data import (from ChatGPT/External)
        // or a full ExportData from this app
        let configToUse = imported.config;
        let dataToUse = imported.data;
        let typeToUse = imported.type;

        // Auto-detect manual JSON import (simpler structure)
        if (!configToUse) {
            // Try to infer
            if (imported.questions && Array.isArray(imported.questions)) {
                typeToUse = 'exam';
                dataToUse = imported as any;
                configToUse = { mode: 'exam', subject: 'Khác', grade: 'Khác', topic: 'Imported Exam' };
            } else if (imported.sections && Array.isArray(imported.sections)) {
                typeToUse = 'theory';
                dataToUse = imported as any;
                configToUse = { mode: 'theory', subject: 'Khác', grade: 'Khác', topic: 'Imported Lesson' };
            } else if (imported.steps && Array.isArray(imported.steps)) {
                typeToUse = 'polya';
                dataToUse = imported as any;
                configToUse = { mode: 'polya', subject: 'Khác', grade: 'Khác', topic: 'Imported Polya' };
            }
        }

        if (typeToUse === 'theory') {
          setStudyGuideData(dataToUse as StudyGuideData);
          setExamData(null);
          setPolyaData(null);
        } else if (typeToUse === 'polya') {
          setPolyaData(dataToUse as PolyaData);
          setExamData(null);
          setStudyGuideData(null);
        } else {
          setExamData(dataToUse as ExamMatrix);
          setStudyGuideData(null);
          setPolyaData(null);
        }
        setConfig(configToUse);
        setStep('preview');
        setRole('teacher');
        setError(null);
      } catch (err: any) {
        setError("Lỗi đọc file: " + err.message);
      }
    };
    reader.readAsText(file);
  };

