const App: React.FC = () => {
  const [step, setStep] = useState<AppStep>('landing');
  const [loading, setLoading] = useState(false);
  const [config, setConfig] = useState<ExamConfig | null>(null);
  const [role, setRole] = useState<'teacher' | 'student' | null>(null);
  const [selectedMode, setSelectedMode] = useState<'exam' | 'matrix' | 'theory' | 'polya' | null>(null);
  const [showUserGuide, setShowUserGuide] = useState(false);
  const [showQuestionBank, setShowQuestionBank] = useState(false); 
  const [showGlobalSettings, setShowGlobalSettings] = useState(false);

  // Custom API Key State
  const [apiKey, setApiKey] = useState(() => {
    try {
      if (typeof window !== 'undefined') {
        return localStorage.getItem('user_gemini_api_key') || '';
      }
    } catch(e) {}
    return '';
  });

  // Save Modal States
  const [showSaveModal, setShowSaveModal] = useState(false);
  const [pendingSaveData, setPendingSaveData] = useState<{type: 'exam'|'theory'|'polya', data: any} | null>(null);

  const [bank, setBank] = useState<BankItem[]>([]); 
  const [googleScriptUrl, setGoogleScriptUrl] = useState<string>(''); 
  const [isSyncing, setIsSyncing] = useState(false);

  const [guideTab, setGuideTab] = useState<'general' | 'shortcuts' | 'templates' | 'faq' | 'prompts'>('general');
  const [copiedPrompt, setCopiedPrompt] = useState<string | null>(null);

  const [isDarkMode, setIsDarkMode] = useState(() => {
    try {
      if (typeof window !== 'undefined') {
        const saved = localStorage.getItem('theme');
        if (saved) return saved === 'dark';
        return window.matchMedia('(prefers-color-scheme: dark)').matches;
      }
    } catch (e) {}
    return false;
  });

  const handleSaveApiKey = (key: string) => {
    setApiKey(key);
    localStorage.setItem('user_gemini_api_key', key);
    alert('Đã lưu API Key thành công!');
    setShowGlobalSettings(false);
  };

  // Global Shortcut for Dark Mode
  useEffect(() => {
    const handleGlobalKeyDown = (e: KeyboardEvent) => {
      // Ignore if user is typing in an input
      if (e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement) return;

      if (e.key.toLowerCase() === 'q') {
        setIsDarkMode(prev => !prev);
      }
    };

    window.addEventListener('keydown', handleGlobalKeyDown);
    return () => window.removeEventListener('keydown', handleGlobalKeyDown);
  }, []);

  // Load Bank and Settings
  useEffect(() => {
    try {
      const savedBank = localStorage.getItem('ai_studio_bank');
      if (savedBank) {
        setBank(JSON.parse(savedBank));
      }
      const savedUrl = localStorage.getItem('ai_studio_gas_url');
      if (savedUrl) {
        setGoogleScriptUrl(savedUrl);
      }
    } catch (e) {
      console.error("Failed to load data from storage", e);
    }
  }, []);

  // Save Bank to Storage
  useEffect(() => {
    try {
      localStorage.setItem('ai_studio_bank', JSON.stringify(bank));
    } catch (e) {
      console.error("Failed to save bank to storage", e);
      alert("Cảnh báo: Bộ nhớ trình duyệt đã đầy. Một số bài học có thể không được lưu. Hãy xóa bớt bài cũ hoặc đồng bộ lên Google Sheet.");
    }
  }, [bank]);

  const handleSaveConfig = (url: string) => {
    setGoogleScriptUrl(url);
    localStorage.setItem('ai_studio_gas_url', url);
    alert("Đã lưu địa chỉ kết nối Google Sheet.");
  };

  useEffect(() => {
    const html = document.documentElement;
    if (isDarkMode) {
      html.classList.add('dark');
      localStorage.setItem('theme', 'dark');
    } else {
      html.classList.remove('dark');
      localStorage.setItem('theme', 'light');
    }
  }, [isDarkMode]);

  const [examData, setExamData] = useState<ExamMatrix | null>(null);
  const [studyGuideData, setStudyGuideData] = useState<StudyGuideData | null>(null);
  const [polyaData, setPolyaData] = useState<PolyaData | null>(null);
  const [error, setError] = useState<string | null>(null);

  // --- Bank Functions ---
  const handleSaveToBank = () => {
    if (!config) return;

    let currentData;
    let type: 'exam' | 'theory' | 'polya' = 'exam';

    if (config.mode === 'theory') {
        currentData = studyGuideData;
        type = 'theory';
    } else if (config.mode === 'polya') {
        currentData = polyaData;
        type = 'polya';
    } else {
        currentData = examData;
        type = 'exam';
    }

    if (!currentData) return;

    // Check size roughly
    const jsonString = JSON.stringify(currentData);
    if (jsonString.length > 3000000) { 
        if (!confirm("Bài học này có dung lượng lớn (có thể do chứa nhiều ảnh). Việc lưu có thể làm đầy bộ nhớ trình duyệt. Bạn có muốn tiếp tục?")) return;
    }

    setPendingSaveData({ type, data: currentData });
    setShowSaveModal(true);
  };

  const executeSaveToBank = (title: string, tags: string[]) => {
    if (!pendingSaveData || !config) return;

    const newItem: BankItem = {
        id: Date.now().toString(),
        title: title,
        tags: tags,
        date: Date.now(),
        type: pendingSaveData.type,
        data: pendingSaveData.data,
        config: config
    };

    setBank(prev => [newItem, ...prev]);
    setShowSaveModal(false);
    setPendingSaveData(null);
    alert("Đã lưu vào Ngân hàng bài học thành công!");
  };

  const handleDeleteFromBank = (id: string) => {
    if (confirm("Bạn có chắc chắn muốn xóa bài này khỏi ngân hàng?")) {
        setBank(prev => prev.filter(item => item.id !== id));
    }
  };

  const handleRenameBankItem = (id: string) => {
    const item = bank.find(b => b.id === id);
    if (!item) return;
    const newTitle = window.prompt("Nhập tên mới cho bài học:", item.title);
    if (newTitle && newTitle.trim() !== "") {
        setBank(prev => prev.map(b => b.id === id ? { ...b, title: newTitle } : b));
    }
  };

  const handleLoadFromBank = (item: BankItem) => {
    setConfig(item.config);
    if (item.type === 'theory') {
        setStudyGuideData(item.data);
